no `<musica/…>`.

```cpp
// SPDX-License-Identifier: Apache-2.0
//
// Worked MIEM API example — constructs a MIEMConfig programmatically
// and runs one emissions timestep. Mirrors how a non-musica caller
// (ad-hoc host integration, test harness, standalone tool) feeds MIEM.
// Musica's YAML-to-MIEMConfig path is shown in musica's examples, not
// here.
//
// See docs/config-architecture.md §3 for struct ownership, §5 for the
// public API shape, and docs/example/README.md for a prose walkthrough.

#include <miem/config.hpp>            // MIEMConfig, SourceConfig,
                                      // SpeciesMap, DatasetDescriptor,
                                      // Regridding + enums
#include <miem/emissions_module.hpp>  // EmissionsModule
#include <miem/emis_state.hpp>        // EmisState

#include <iostream>
#include <iomanip>

using namespace miem;

int main()
{
  // --------------------------------------------------------------
  // 1. Build the shared species maps (CAMS, NEI, FINN, MEGAN).
  //    Each SpeciesMap belongs to a mechanism; mappings can split one
  //    inventory species across multiple mechanism species with
  //    scaling factors (mass conservation: per-inventory-species sum
  //    ≤ 1.0). The CAMS map demonstrates NOx and NMVOC splits.
  // --------------------------------------------------------------
  SpeciesMap mozart_t1_from_cams { .mechanism_ = "MOZART-T1" };
  mozart_t1_from_cams.mappings_ = {
    { .inventory_species_ = "NOx",   .mechanism_species_ = "NO",      .scaling_factor_ = 0.9 },
    { .inventory_species_ = "NOx",   .mechanism_species_ = "NO2",     .scaling_factor_ = 0.1 },
    { .inventory_species_ = "SO2",   .mechanism_species_ = "SO2",     .scaling_factor_ = 1.0 },
    { .inventory_species_ = "CO",    .mechanism_species_ = "CO",      .scaling_factor_ = 1.0 },
    { .inventory_species_ = "NH3",   .mechanism_species_ = "NH3",     .scaling_factor_ = 1.0 },
    { .inventory_species_ = "BC",    .mechanism_species_ = "BC",      .scaling_factor_ = 1.0 },
    { .inventory_species_ = "OC",    .mechanism_species_ = "OC",      .scaling_factor_ = 1.0 },
    // Lumped NMVOC split. Sum = 0.65 < 1.0 (35% routed to species
    // MOZART-T1 does not track — intentionally dropped, HEMCO-style).
    { .inventory_species_ = "NMVOC", .mechanism_species_ = "BIGALK",  .scaling_factor_ = 0.30 },
    { .inventory_species_ = "NMVOC", .mechanism_species_ = "BIGENE",  .scaling_factor_ = 0.20 },
    { .inventory_species_ = "NMVOC", .mechanism_species_ = "TOLUENE", .scaling_factor_ = 0.15 },
  };

  SpeciesMap mozart_t1_from_nei   = /* similar, NEI-native SAPRAC */;
  SpeciesMap mozart_t1_from_finn  = /* similar, fire-specific ratios */;
  SpeciesMap mozart_t1_from_megan = /* similar, biogenic */;

  // --------------------------------------------------------------
  // 2. Build the dataset descriptor for the legacy CEDS inventory.
  //    ECCAD-conforming files do not need a descriptor.
  // --------------------------------------------------------------
  DatasetDescriptor ceds_legacy {
    .variable_prefix_         = "emiss_",
    .flux_units_              = "kg m-2 s-1",
    .unit_conversion_factor_  = 1.0,
    .time_dimension_          = "time",
    .cell_dimension_          = "ncol",
    .species_rename_ = {
      { "emiss_no",  "NO"  },
      { "emiss_co",  "CO"  },
      { "emiss_so2", "SO2" },
    },
  };

  // --------------------------------------------------------------
  // 3. Build the sources. All five are `mode: offline` — v1 scope.
  //    Order in the vector does not determine precedence; that's
  //    encoded in (category, hierarchy).
  // --------------------------------------------------------------
  SourceConfig cams_anthro {
    .name_                   = "cams anthro",
    .mode_                   = SourceMode::Offline,
    .type_                   = SourceType::Anthropogenic,
    .file_pattern_           = "/glade/campaign/acom/emissions/cams/v6.2/"
                               "CAMS-GLOB-ANT_v6.2_{YYYY}-{MM}.nc",
    .convention_             = InventoryConvention::ECCAD,
    .species_map_            = mozart_t1_from_cams,         // inlined
    .temporal_interpolation_ = TemporalInterpolation::Linear,
    .vertical_injection_     = VerticalInjection::Surface,
    .category_               = 0,
    .hierarchy_              = 1,
    .scaling_factor_         = 1.0,
    .sector_                 = "anthropogenic",
  };

  SourceConfig nei_us_anthro = /* same category=0, hierarchy=2, wins over CAMS in US cells */;

  SourceConfig finn_fires = /* category=1, hierarchy=1, sector=fire, TemporalInterpolation::Nearest */;

  SourceConfig ceds_us_override {
    // Uses the legacy descriptor path (non-ECCAD file).
    // …
    .convention_ = InventoryConvention::Descriptor,
    .descriptor_ = ceds_legacy,                            // inlined
    .category_   = 0, .hierarchy_ = 3,                     // wins over both CAMS and NEI
    // …
  };

  SourceConfig megan_offline_climo = /* biogenic climatology; sector=biogenic */;

  // --------------------------------------------------------------
  // 4. Aspirational v2/v3 source shapes — shown so the API surface
  //    is visible, but commented out so this example compiles under
  //    v1 semantics. Each would raise the named error at construct
  //    time (or during parse, if a YAML path were used).
  //
  //    v2 plume-rise for 3D fire fluxes:
  // --------------------------------------------------------------
  #if 0  // v1: EmissionsModule throws UnsupportedVerticalInjection
  SourceConfig finn_plume_3d {
    .name_                   = "finn plume 3d",
    .mode_                   = SourceMode::Offline,
    .type_                   = SourceType::Fire,
    .file_pattern_           = "/.../finn-3d/FINN_3D_{YYYY}{DDD}.nc",
    .vertical_injection_     = VerticalInjection::Plume,   // v2
    // …
  };
  #endif

  //    v2 online dust, sea-salt; v3 online biogenic (MEGAN),
  //    lightning NOx, DMS — all `mode: Online` with a provider
  //    string. Shown in one #if 0 block so the reader sees the full
  //    surface.
  #if 0  // v1: EmissionsModule throws OnlineSourcesNotSupported
  SourceConfig dust_online {
    .name_     = "dust online",
    .mode_     = SourceMode::Online,
    .type_     = SourceType::Dust,
    .provider_ = "quacs.dust",                             // provider-string shape TBD (see README open questions)
    // …
  };
  SourceConfig seasalt_online = /* provider_: "quacs.seasalt" */;
  SourceConfig lightning_nox  = /* provider_: "quacs.lightning" */;
  SourceConfig megan_online   = /* provider_: "quacs.megan"    */;
  #endif

  // --------------------------------------------------------------
  // 5. Regridding: v1 accepts only None (data already on target
  //    grid). SCRIP regridding lands in v1.x; shown here so the
  //    field shape is visible.
  // --------------------------------------------------------------
  Regridding regridding { .type_ = RegriddingType::None };
  #if 0  // v1: EmissionsModule throws UnsupportedRegriddingType
  regridding.type_          = RegriddingType::SCRIP;
  regridding.weights_file_  = "/glade/.../weights/cams_to_mpas120km.nc";
  #endif

  // --------------------------------------------------------------
  // 6. Assemble the MIEMConfig. MIEMConfig is a plain struct; no
  //    builder, no yaml-cpp, no MechanismConfiguration types.
  // --------------------------------------------------------------
  MIEMConfig cfg {
    .version_    = "1.0.0",
    .regridding_ = regridding,
    .sources_    = { cams_anthro, nei_us_anthro, finn_fires,
                     ceds_us_override, megan_offline_climo },
  };

  // --------------------------------------------------------------
  // 7. Create the module. Dimensions come from the host (MPAS-A
  //    120km global mesh shown here; any grid works — regridding
  //    weights, if configured, remap source-grid fluxes onto these
  //    cells).
  // --------------------------------------------------------------
  const int n_cells       = 163842;
  const int n_vert_levels = 60;
  EmissionsModule module(cfg, n_cells, n_vert_levels);

  // --------------------------------------------------------------
  // 8. Run one timestep. Signature is one of the open questions —
  //    shown here as `Run(sim_time, dt)`; see README.
  // --------------------------------------------------------------
  const double sim_time_sec = /* seconds since model epoch */;
  const double dt_sec       = 600.0;  // 10 minutes
  EmisState state = module.Run(sim_time_sec, dt_sec);

  // --------------------------------------------------------------
  // 9. Consume outputs.
  //
  //    - state.surface_flux[cell, mechanism_species]
  //        Host pushes these to MICM as EMIS.* rate parameters.
  //    - state.tendency[cell, level, mechanism_species]
  //        Populated only if regridding produced vertical structure
  //        or if vertical_injection was `Plume` (aspirational).
  //    - state.sector_fluxes[sector_label][cell, mechanism_species]
  //        Diagnostic. Populated iff the host asked for it at
  //        construct time (TBD — open question: opt-in flag vs
  //        always-on).
  // --------------------------------------------------------------
  std::cout << std::scientific << std::setprecision(3);
  std::cout << "Cell 0, NO  surface flux: " << state.surface_flux_(0, "NO")  << " kg m-2 s-1\n";
  std::cout << "Cell 0, NO2 surface flux: " << state.surface_flux_(0, "NO2") << " kg m-2 s-1\n";
  std::cout << "Cell 0, CO  surface flux: " << state.surface_flux_(0, "CO")  << " kg m-2 s-1\n";
  std::cout << "Sector 'anthropogenic', cell 0, NO: "
            << state.sector_fluxes_.at("anthropogenic")(0, "NO") << "\n";

  return 0;
}
```

